Q: using array.findIndex() on state in React A: <pre><code>assignAttribute = (ident) =&gt; {
    var x = document.getElementById(ident).name;
    var holder = this.state.currentRecipe;
    var temp = null;

    // Check for duplicates
    var check = holder[x].findIndex(item =&gt; item === this.state[x]);

    if (check === -1) {
        console.log('ok');

        // Update holder based on the type of input
        x === 'title' ? temp = update(holder, { [x]: { $set: this.state[x] } })
            : x === 'ingredients' ? temp = update(holder, { [x]: { $push: [this.state[x]] } })
                : temp = update(holder, { [x]: { $push: [this.state[x]] } });

        // Update state
        this.setState({ currentRecipe: temp });
    } else {
        console.log('already exists');
    }

    console.log(check);
    console.log(this.state[x]);
    console.log(holder[x]);
}
</code></pre>
